record.field:
eg_companies = self.env.companies.filtered(lambda c: c.country_id.code == 'EG')
payslips = self.env['hr.payslip'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', eg_companies.ids),
])
payslips = payslips.filtered(lambda p: p._origin)
warning_records = self.env['hr.payslip']
warning_details = defaultdict(list)
for payslip in payslips:
    warning_fields = ["passport_id", "l10n_eg_ssn", "job_title"]
    employee_fields = payslip.employee_id._fields
    for field in warning_fields:
        if not payslip.employee_id[field]:
            warning_records |= payslip
            warning_details[payslip].append({
                'message': _get_payroll_translation("Missing field '%(field_label)s' to print ETA-form2.", field_label=employee_fields[field].string),
                'action_text': _get_payroll_translation('Employee'),
                'action': payslip.employee_id._get_records_action(),
                'level': 'warning',
            })
